class MountainArray:
    def __init__(self, arr):
        self.arr = arr

    def get(self, index):
        return self.arr[index]

    def length(self):
        return len(self.arr)


def find_in_mountain_array(target, arr):
    mountain_arr = MountainArray(arr)
    n = mountain_arr.length()

    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if mountain_arr.get(mid) < mountain_arr.get(mid + 1):
            lo = mid + 1
        else:
            hi = mid
    peak = lo

    lo, hi = 0, peak
    while lo <= hi:
        mid = (lo + hi) // 2
        val = mountain_arr.get(mid)
        if val == target:
            return mid
        if val < target:
            lo = mid + 1
        else:
            hi = mid - 1

    lo, hi = peak, n - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        val = mountain_arr.get(mid)
        if val == target:
            return mid
        if val > target:
            lo = mid + 1
        else:
            hi = mid - 1

    return -1

